import test from 'node:test';
import assert from 'node:assert/strict';
import {
  CredentialLifecycleTimelineReadModel,
  ExpiryRenewalEvaluation,
  RecurringObligationProjection,
  RenewalCaseHistory,
  LifecycleNotificationProjection,
  LifecycleDependencyImpactTraversal,
  LifecycleSelectiveReevaluation,
  ContinuousComplianceProjection,
  LifecycleHistoricalReplay,
} from '../src/lifecycle/index.ts';

type Family='EXPIRY_RENEWAL'|'CHANGED_EVIDENCE'|'CHANGED_REQUIREMENT';

const PUBLIC_APIS=Object.freeze([
  CredentialLifecycleTimelineReadModel,
  ExpiryRenewalEvaluation,
  RecurringObligationProjection,
  RenewalCaseHistory,
  LifecycleNotificationProjection,
  LifecycleDependencyImpactTraversal,
  LifecycleSelectiveReevaluation,
  ContinuousComplianceProjection,
  LifecycleHistoricalReplay,
]);
assert.equal(PUBLIC_APIS.length,9);
for(const api of PUBLIC_APIS) assert.equal(typeof api,'function');

function stableReasons(family:Family){
  return Object.freeze((family==='EXPIRY_RENEWAL'
    ? ['AS_WAS_SEPARATE','CURRENT_PROJECTION_ONLY','EXPIRY_RENEWAL_CHAIN','NOTIFICATION_NON_AUTHORITATIVE']
    : family==='CHANGED_EVIDENCE'
      ? ['AS_WAS_SEPARATE','CHANGED_EVIDENCE','SELECTIVE_REEVALUATION','TARGETED_DEPENDENCY_TRAVERSAL']
      : ['AS_WAS_SEPARATE','CHANGED_REQUIREMENT','SELECTIVE_REEVALUATION','TARGETED_DEPENDENCY_TRAVERSAL']
  ).sort());
}

function evidence(index:number,family:Family){
  const caseId=`M06S10-${String(index).padStart(3,'0')}`;
  const sliceChain=family==='EXPIRY_RENEWAL'
    ? ['S01','S02','S03','S04','S05','S08','S09']
    : ['S06','S07','S08','S09'];
  return Object.freeze({
    caseId,
    family,
    sliceChain:Object.freeze(sliceChain),
    reasonCodes:stableReasons(family),
    currentReference:`current:${family.toLowerCase()}:${caseId}`,
    historicalReference:`historical:${family.toLowerCase()}:${caseId}`,
    asWasSeparated:true,
    asIsSeparated:true,
    targetedReevaluation:family!=='EXPIRY_RENEWAL',
    globalRebuildAuthorized:false,
    notificationDeliveryAuthoritative:false,
    assignmentInferenceAuthorized:false,
    authorizationAuthority:false,
    credentialStateMutated:false,
    historicalDecisionMutated:false,
    complianceStateChanged:false,
    providerInvoked:false,
    eventsEmitted:0,
    physicalDeletionAuthorized:false,
    productionReleaseAuthorized:false,
    metadataOnly:true,
  } as const);
}

